SELECT r.namespace_id, r.run_id, r.report_id, r.version_no, r.source_revision, r.spec_hash, r.plan_key, r.active_key, r.status, r.requested_by, r.target_json, r.requested_at, r.deadline_at, r.created_at, r.created_by, r.updated_at, r.updated_by FROM (SELECT * FROM (SELECT w.namespace_id, w.run_id, w.report_id, w.version_no, w.source_revision, w.spec_hash, w.plan_key, w.active_key, w.status, w.requested_by, w.target_json, w.requested_at, w.deadline_at, w.created_at, w.created_by, w.updated_at, w.updated_by FROM component_warmup_runs w) run) r WHERE $criteria.CompositeIn("r", $Unsafe.ProjectCurrentRunParentKeys($CurrentSchedule))